#include "layereditor.h"
#include <QDialog>
#include <QDialogButtonBox>
#include <QFormLayout>
#include <QVBoxLayout>
#include <QLabel>
#include <QPushButton>
#include <QColorDialog>
#include <QDoubleSpinBox>
#include <QCheckBox>

bool editLayerPresentation(ga::Layer &layer,bool en,QWidget *parent){
 const auto text=[&](const char *vi,const char *english){return QString::fromUtf8(en?english:vi);};
 QDialog dialog(parent);dialog.setObjectName("layer-editor");dialog.setWindowTitle(en?layer.en:layer.vi);dialog.resize(460,620);auto layout=new QVBoxLayout(&dialog);layout->setContentsMargins(18,16,18,16);layout->setSpacing(10);auto form=new QFormLayout();layout->addLayout(form);form->setVerticalSpacing(8);form->setHorizontalSpacing(12);
 const auto spin=[&](const char *name,double value,double lo,double hi,int decimals=2){auto s=new QDoubleSpinBox(&dialog);s->setObjectName(name);s->setRange(lo,hi);s->setDecimals(decimals);s->setValue(value);return s;};
 const auto colorButton=[&](const char *name,QColor value){if(!value.isValid())value=QColor("#34332f");auto button=new QPushButton(&dialog);button->setObjectName(name);button->setProperty("paint",value.name());button->setText("  "+value.name().toUpper());button->setStyleSheet("text-align:left;padding-left:8px;border-left:18px solid "+value.name()+";");QObject::connect(button,&QPushButton::clicked,&dialog,[button,&dialog,text]{const auto c=QColorDialog::getColor(QColor(button->property("paint").toString()),&dialog,text("Chọn màu","Choose color"));if(c.isValid()){button->setProperty("paint",c.name());button->setText("  "+c.name().toUpper());button->setStyleSheet("text-align:left;padding-left:8px;border-left:18px solid "+c.name()+";");}});return button;};
 const auto &o=layer.presentation;auto color=colorButton("layer-color",layer.color);form->addRow(text("Màu tô","Fill color"),color);auto opacity=spin("layer-opacity",layer.opacity*100,0,100,0);opacity->setSuffix(" %");form->addRow(text("Độ đậm","Opacity"),opacity);
 auto outline=new QCheckBox(text("Hiện nét viền","Show outline"),&dialog);outline->setObjectName("layer-outline");outline->setChecked(o.contains("stroke")&&o["stroke"]!="none");form->addRow(outline);auto stroke=colorButton("layer-stroke",QColor(o["stroke"].toString("#34332f")));if(!QColor(o["stroke"].toString()).isValid())stroke->setProperty("paint","#34332f");form->addRow(text("Màu nét","Outline color"),stroke);auto strokeWidth=spin("layer-stroke-width",o["strokeWidth"].toDouble(.2),0,8);form->addRow(text("Bề dày nét đồ họa","Graphic outline width"),strokeWidth);
 auto customWidth=new QCheckBox(text("Đặt bề rộng đường","Set line width"),&dialog);customWidth->setObjectName("layer-custom-width");customWidth->setChecked(o.contains("lineWidth"));form->addRow(customWidth);auto width=spin("layer-line-width",o["lineWidth"].toDouble(6),.1,200);width->setSuffix(" m");form->addRow(text("Bề rộng ký hiệu","Symbol width"),width);auto minWidth=spin("layer-line-min",o["lineMinWidth"].toDouble(.2),0,8);form->addRow(text("Nét tối thiểu đồ họa","Minimum graphic width"),minWidth);auto hierarchy=new QCheckBox(text("Phân cấp theo loại đường","Scale by road hierarchy"),&dialog);hierarchy->setObjectName("layer-road-hierarchy");hierarchy->setChecked(o["roadHierarchy"].toBool());form->addRow(hierarchy);
 auto tree=spin("layer-tree-radius",o["tree"].toObject()["radius"].toDouble(2.4),.1,30);tree->setSuffix(" m");if(layer.id=="trees")form->addRow(text("Bán kính tán minh họa","Illustrative canopy radius"),tree);else tree->hide();
 const auto sh=o["shadow"].toObject();auto shadow=new QCheckBox(text("Bóng lệch đồ họa","Graphic offset shadow"),&dialog);shadow->setObjectName("layer-shadow");shadow->setChecked(!sh.isEmpty());form->addRow(shadow);auto shadowColor=colorButton("layer-shadow-color",QColor(sh["color"].toString("#34332f")));form->addRow(text("Màu bóng","Shadow color"),shadowColor);auto shadowOpacity=spin("layer-shadow-opacity",sh["opacity"].toDouble(.12)*100,0,100,0);shadowOpacity->setSuffix(" %");form->addRow(text("Độ đậm bóng","Shadow opacity"),shadowOpacity);auto dx=spin("layer-shadow-dx",sh["dx"].toDouble(7),-50,50);dx->setSuffix(" m");form->addRow(text("Lệch về đông","East offset"),dx);auto dy=spin("layer-shadow-dy",sh["dy"].toDouble(7),-50,50);dy->setSuffix(" m");form->addRow(text("Lệch về nam","South offset"),dy);
 const auto enabled=[=]{stroke->setEnabled(outline->isChecked());strokeWidth->setEnabled(outline->isChecked());width->setEnabled(customWidth->isChecked());minWidth->setEnabled(customWidth->isChecked());hierarchy->setEnabled(customWidth->isChecked());shadowColor->setEnabled(shadow->isChecked());shadowOpacity->setEnabled(shadow->isChecked());dx->setEnabled(shadow->isChecked());dy->setEnabled(shadow->isChecked());};for(auto box:{outline,customWidth,shadow})QObject::connect(box,&QCheckBox::toggled,&dialog,enabled);enabled();
 auto note=new QLabel(text("Bề rộng, tán cây và bóng lệch là ký hiệu trình bày. Bề rộng đường và đường kính tán có ghi trong nguồn được ưu tiên. Bóng này không phải kết quả tính nắng.","Widths, fallback canopies and offset shadows are presentation symbols. Recorded road widths and crown diameters take precedence. These shadows are not a solar calculation."),&dialog);note->setWordWrap(true);note->setObjectName("hint");layout->addWidget(note);auto buttons=new QDialogButtonBox(QDialogButtonBox::Save|QDialogButtonBox::Cancel,&dialog);buttons->button(QDialogButtonBox::Save)->setText(text("Lưu","Save"));buttons->button(QDialogButtonBox::Save)->setProperty("accent",true);buttons->button(QDialogButtonBox::Cancel)->setText(text("Hủy","Cancel"));layout->addWidget(buttons);QObject::connect(buttons,&QDialogButtonBox::accepted,&dialog,&QDialog::accept);QObject::connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);
 if(dialog.exec()!=QDialog::Accepted)return false;
 auto next=layer;next.color=QColor(color->property("paint").toString());next.opacity=opacity->value()/100;auto options=o;options["stroke"]=outline->isChecked()?stroke->property("paint").toString():"none";options["strokeWidth"]=strokeWidth->value();for(const auto key:{"lineWidth","lineMinWidth","roadHierarchy"})options.remove(key);if(customWidth->isChecked()){options["lineWidth"]=width->value();options["lineMinWidth"]=minWidth->value();options["roadHierarchy"]=hierarchy->isChecked();}if(layer.id=="trees"){auto canopy=o["tree"].toObject();canopy["radius"]=tree->value();options["tree"]=canopy;}options.remove("shadow");if(shadow->isChecked())options["shadow"]=QJsonObject{{"color",shadowColor->property("paint").toString()},{"opacity",shadowOpacity->value()/100},{"dx",dx->value()},{"dy",dy->value()}};next.presentation=options;layer=next;return true;
}
